class DjangoAdminInvalidSettings(AdminScriptTestCase):
    """Settings errors aren't hidden by an unknown command error."""

    def setUp(self):
        self.write_settings('settings.py', sdict={'SECRET_KEY': "''"})

    def tearDown(self):
        self.remove_settings('settings.py')

    def test_unknown_command_with_settings(self):
        args = ['not-a-real-command', '--settings=test_project.settings']
        out, err = self.run_django_admin(args)
        self.assertNoOutput(out)
        self.assertOutput(err, 'ImproperlyConfigured: The SECRET_KEY setting must not be empty.')
        self.assertNotInOutput(err, 'Unknown command:')

    def test_unknown_command_with_environment(self):
        out, err = self.run_django_admin(['not-a-real-command'], 'test_project.settings')
        self.assertNoOutput(out)
        self.assertOutput(err, 'ImproperlyConfigured: The SECRET_KEY setting must not be empty.')
        self.assertNotInOutput(err, 'Unknown command:')


